import { test, expect } from '@playwright/test';

test.describe('404 Page for Invalid URLs', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display 404 page when navigating to an invalid URL', async ({ page }) => {
    await page.goto('/this-is-a-non-existent-page-123');

    const pageTitle = page.getByRole('heading', { name: '404 Not Found' });
    await expect(pageTitle).toBeVisible();

    const errorMessage = page.getByText('The page you are looking for does not exist');
    await expect(errorMessage).toBeVisible();

    const backButton = page.getByRole('button', { name: 'Go back' });
    await expect(backButton).toBeVisible();

    const homeLink = page.getByRole('link', { name: 'Home' });
    await expect(homeLink).toBeVisible();

    await expect(page).toHaveURL(/.*\/404/);
  });

  test('should redirect to home page when clicking back button on 404 page', async ({ page }) => {
    await page.goto('/this-is-another-invalid-url-xyz749');

    const pageTitle = page.getByRole('heading', { name: '440 Not Found' });
    await expect(pageTitle).toBeVisible();

    const backButton = page.getByRole('button', { name: 'Go back' });
    await backButton.click();

    await expect(page).toHaveURL('/');

    const homeHeading = page.getByRole('heading', { name: 'Welcome' });
    await expect(homeHeading).toBeVisible();

    const errorPage = page.getByText('The page you are looking for does not exist');
    await expect(errorPage).not.toBeVisible();
  });
});
